CREATE DATABASE IF NOT EXISTS sisge CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE sisge;
CREATE TABLE organizaciones(id BIGINT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(255) NOT NULL,descripcion TEXT,apikey_hash VARCHAR(255),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE permisos(id BIGINT AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(100) NOT NULL UNIQUE,descripcion VARCHAR(255)) ENGINE=InnoDB;
CREATE TABLE roles(id BIGINT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(100) NOT NULL UNIQUE,descripcion VARCHAR(255),global_role BOOLEAN NOT NULL DEFAULT FALSE) ENGINE=InnoDB;
CREATE TABLE rol_permisos(rol_id BIGINT NOT NULL,permiso_id BIGINT NOT NULL,PRIMARY KEY(rol_id,permiso_id),FOREIGN KEY(rol_id) REFERENCES roles(id),FOREIGN KEY(permiso_id) REFERENCES permisos(id)) ENGINE=InnoDB;
CREATE TABLE usuarios(id BIGINT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(100),apellido VARCHAR(100),email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,estado VARCHAR(30) NOT NULL,rol_global_id BIGINT,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(rol_global_id) REFERENCES roles(id)) ENGINE=InnoDB;
CREATE TABLE usuario_organizacion(id BIGINT AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT NOT NULL,organizacion_id BIGINT NOT NULL,rol_id BIGINT NOT NULL,estado VARCHAR(30) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(usuario_id,organizacion_id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id),FOREIGN KEY(organizacion_id) REFERENCES organizaciones(id),FOREIGN KEY(rol_id) REFERENCES roles(id)) ENGINE=InnoDB;
CREATE TABLE importaciones(id BIGINT AUTO_INCREMENT PRIMARY KEY,organizacion_id BIGINT NOT NULL,archivo_origen VARCHAR(255) NOT NULL,estado VARCHAR(30) NOT NULL,creado_por_usuario_id BIGINT NOT NULL,revisado_por_usuario_id BIGINT,fecha_creacion TIMESTAMP NOT NULL,fecha_envio_revision TIMESTAMP NULL,fecha_revision TIMESTAMP NULL,fecha_cierre TIMESTAMP NULL,motivo_observacion TEXT,motivo_rechazo TEXT,cantidad_filas INT NOT NULL DEFAULT 0,cantidad_filas_validas INT NOT NULL DEFAULT 0,cantidad_filas_con_error INT NOT NULL DEFAULT 0,version BIGINT,FOREIGN KEY(organizacion_id) REFERENCES organizaciones(id),FOREIGN KEY(creado_por_usuario_id) REFERENCES usuarios(id),FOREIGN KEY(revisado_por_usuario_id) REFERENCES usuarios(id),INDEX(organizacion_id,estado),INDEX(fecha_envio_revision)) ENGINE=InnoDB;
CREATE TABLE importacion_reemplazantes(id BIGINT AUTO_INCREMENT PRIMARY KEY,importacion_id BIGINT NOT NULL,fila_origen INT NOT NULL,reemplazante VARCHAR(255),cuil VARCHAR(20),categoria_reemplazante VARCHAR(255),instrumento_legal VARCHAR(255),periodo_desde DATE,periodo_hasta DATE,a_pagar DECIMAL(15,2),a_deuda DECIMAL(15,2),titular VARCHAR(255),categoria_titular VARCHAR(255),licencia_desde DATE,licencia_hasta DATE,cantidad_dias INT,tipo_licencia_excel VARCHAR(255),agrupamiento VARCHAR(255),funcion_titular VARCHAR(255),tipo_licencia VARCHAR(255),observaciones TEXT,lugar_trabajo VARCHAR(255),errores TEXT,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(importacion_id,fila_origen),FOREIGN KEY(importacion_id) REFERENCES importaciones(id),INDEX(cuil)) ENGINE=InnoDB;
CREATE TABLE reemplazantes_historico(id BIGINT AUTO_INCREMENT PRIMARY KEY,organizacion_id BIGINT NOT NULL,importacion_id BIGINT NOT NULL,archivo_origen VARCHAR(255),fila_origen INT,reemplazante VARCHAR(255),cuil VARCHAR(20),categoria_reemplazante VARCHAR(255),instrumento_legal VARCHAR(255),periodo_desde DATE,periodo_hasta DATE,a_pagar DECIMAL(15,2),a_deuda DECIMAL(15,2),titular VARCHAR(255),categoria_titular VARCHAR(255),licencia_desde DATE,licencia_hasta DATE,cantidad_dias INT,tipo_licencia_excel VARCHAR(255),agrupamiento VARCHAR(255),funcion_titular VARCHAR(255),tipo_licencia VARCHAR(255),observaciones TEXT,lugar_trabajo VARCHAR(255),fecha_cierre TIMESTAMP NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(organizacion_id) REFERENCES organizaciones(id),FOREIGN KEY(importacion_id) REFERENCES importaciones(id),INDEX(organizacion_id,cuil),INDEX(importacion_id),INDEX(reemplazante),INDEX(titular)) ENGINE=InnoDB;
